using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: HasIndex is no longer silently ignored; it throws in EF Core 9.
        // Cosmos DB does not support indexes via EF, so remove HasIndex.
        // modelBuilder.Entity<Blog>().HasIndex(b => b.Name); // REMOVED

        // Breaking change 2: Discriminator property renamed from "Discriminator" to "$type".
        // To read existing documents that use "Discriminator", restore the old property name.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 3: Id format changed from "EntityType|Key" to just "Key" in EF Core 9.
        // To read existing documents with id "Blog|1", restore the old id factory behavior.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdGenerator>();
    }
}

// Breaking change 4: Sync I/O now throws by default. See SyncJob.cs for the fix.

class Blog { public string Id { get; set; } public string Name { get; set; }  }

/// <summary>
/// Restores the EF8-style "Blog|{key}" id format for backward compatibility with existing documents.
/// </summary>
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
    {
        var entityType = entry.Metadata.ShortName();
        var key = entry.Property("Id").CurrentValue?.ToString() ?? Guid.NewGuid().ToString();
        return $"{entityType}|{key}";
    }
}

